/* Banque de questions de la formation SAP from the shop floor / SAP vu de l'atelier.
   Générée par outils/sap_course/build.py : ne pas modifier à la main.
   La première option est la bonne réponse ; la page mélange l'ordre. */
window.SAP_Q = [{"id":0,"l":1,"en":{"q":"What kind of system is SAP S/4HANA?","o":["An ERP","An MES","A SCADA system","A PLC programming tool"],"e":"S/4HANA is SAP's ERP: it manages orders, materials, stock, costs and the processes around them."},"fr":{"q":"Quel type de système est SAP S/4HANA ?","o":["Un ERP","Un MES","Un système SCADA","Un logiciel de programmation d'automates"],"e":"S/4HANA est l'ERP de SAP : il gère les commandes, les articles, les stocks, les coûts et les processus qui les entourent."}},{"id":1,"l":1,"en":{"q":"In the ISA-95 model, on which level does an ERP sit?","o":["Level 4","Level 3","Level 2","Level 1"],"e":"Level 4 is business planning and logistics. Level 3 is the MES, level 2 supervision, level 1 control."},"fr":{"q":"Dans le modèle ISA-95, à quel niveau se trouve un ERP ?","o":["Niveau 4","Niveau 3","Niveau 2","Niveau 1"],"e":"Le niveau 4 correspond à la planification et à la logistique. Le niveau 3 est le MES, le 2 la supervision, le 1 le contrôle-commande."}},{"id":2,"l":1,"en":{"q":"Which database does SAP S/4HANA run on?","o":["Only SAP HANA","Any SQL database","Oracle only","Microsoft SQL Server"],"e":"S/4HANA was built for SAP HANA, SAP's in-memory database, and runs only on it."},"fr":{"q":"Sur quelle base de données tourne SAP S/4HANA ?","o":["Uniquement SAP HANA","N'importe quelle base SQL","Uniquement Oracle","Microsoft SQL Server"],"e":"S/4HANA a été conçu pour SAP HANA, la base de données en mémoire de SAP, et ne tourne que sur elle."}},{"id":3,"l":1,"en":{"q":"Which SAP organisational unit usually represents a factory?","o":["The plant","The company code","The client","The storage location"],"e":"The plant is the unit for production, planning and stock. A factory or a site is usually one plant."},"fr":{"q":"Quelle unité organisationnelle SAP représente généralement une usine ?","o":["La division (plant)","La société (company code)","Le mandant (client)","Le magasin (storage location)"],"e":"La division (plant) est l'unité de la production, de la planification et du stock. Une usine ou un site correspond en général à une division."}},{"id":4,"l":1,"en":{"q":"What is a storage location?","o":["A place where stock is kept within a plant","A legal entity","A sales office","A production line"],"e":"A plant can have several storage locations, for example raw materials, line side and finished goods."},"fr":{"q":"Qu'est-ce qu'un magasin (storage location) ?","o":["Un endroit où le stock est rangé dans une division","Une entité juridique","Un bureau de vente","Une ligne de production"],"e":"Une division peut avoir plusieurs magasins : matières premières, bord de ligne, produits finis, etc."}},{"id":5,"l":1,"en":{"q":"What is a company code?","o":["A legal entity with its own accounts","A password for the company","A plant number","A type of production order"],"e":"The company code is the level where legal financial statements are produced. Plants belong to a company code."},"fr":{"q":"Qu'est-ce qu'une société (company code) ?","o":["Une entité juridique avec sa propre comptabilité","Un mot de passe de l'entreprise","Un numéro de division","Un type d'ordre de fabrication"],"e":"La société est le niveau où l'on établit les comptes légaux. Les divisions sont rattachées à une société."}},{"id":6,"l":1,"en":{"q":"Which of these tasks is NOT done by SAP S/4HANA?","o":["Controlling a motor's speed in real time","Planning what to produce","Valuing stock","Recording production quantities"],"e":"Real-time control belongs to the PLC (level 1). SAP works in hours and days, not in milliseconds."},"fr":{"q":"Laquelle de ces tâches n'est PAS faite par SAP S/4HANA ?","o":["Réguler la vitesse d'un moteur en temps réel","Planifier ce qu'il faut produire","Valoriser le stock","Enregistrer les quantités produites"],"e":"Le contrôle en temps réel est le rôle de l'automate (niveau 1). SAP travaille en heures et en jours, pas en millisecondes."}},{"id":7,"l":1,"en":{"q":"Which module abbreviation stands for production planning?","o":["PP","MM","SD","FI"],"e":"PP is production planning, MM materials management, SD sales and distribution, FI financial accounting."},"fr":{"q":"Quelle abréviation de module désigne la planification de la production ?","o":["PP","MM","SD","FI"],"e":"PP : planification de la production. MM : gestion des articles. SD : ventes et distribution. FI : comptabilité financière."}},{"id":8,"l":1,"en":{"q":"Which system usually sits between SAP and supervision to manage execution on the floor?","o":["An MES","A second ERP","A spreadsheet","An HMI panel"],"e":"The MES (level 3) receives orders from the ERP, follows their execution and reports back."},"fr":{"q":"Quel système se place généralement entre SAP et la supervision pour gérer l'exécution en atelier ?","o":["Un MES","Un second ERP","Un tableur","Un pupitre IHM"],"e":"Le MES (niveau 3) reçoit les ordres de l'ERP, suit leur exécution et renvoie les résultats."}},{"id":9,"l":1,"en":{"q":"What is SAP ECC?","o":["The predecessor of S/4HANA","A cloud MES","An OPC UA server","A database"],"e":"SAP ECC (ERP Central Component) is the previous generation of SAP's ERP. Many companies are moving from ECC to S/4HANA."},"fr":{"q":"Qu'est-ce que SAP ECC ?","o":["Le prédécesseur de S/4HANA","Un MES dans le cloud","Un serveur OPC UA","Une base de données"],"e":"SAP ECC (ERP Central Component) est la génération précédente de l'ERP de SAP. Beaucoup d'entreprises passent d'ECC à S/4HANA."}},{"id":10,"l":2,"en":{"q":"What is SAP Fiori?","o":["SAP's web-based user interface, made of apps","A database","A programming language","A printer driver"],"e":"Fiori apps open in a web browser from the Fiori launchpad, and only show what the user's role needs."},"fr":{"q":"Qu'est-ce que SAP Fiori ?","o":["L'interface web de SAP, composée d'applications","Une base de données","Un langage de programmation","Un pilote d'imprimante"],"e":"Les applications Fiori s'ouvrent dans un navigateur depuis le launchpad Fiori et n'affichent que ce dont le rôle de l'utilisateur a besoin."}},{"id":11,"l":2,"en":{"q":"In SAP GUI, what does typing /nMM03 in the command field do?","o":["Leaves the current transaction and opens MM03","Opens MM03 in a new window","Deletes material MM03","Logs off"],"e":"/n followed by a code ends the current transaction and starts the new one in the same window."},"fr":{"q":"Dans SAP GUI, que fait la saisie de /nMM03 dans le champ de commande ?","o":["Quitte la transaction en cours et ouvre MM03","Ouvre MM03 dans une nouvelle fenêtre","Supprime l'article MM03","Déconnecte l'utilisateur"],"e":"/n suivi d'un code termine la transaction en cours et lance la nouvelle dans la même fenêtre."}},{"id":12,"l":2,"en":{"q":"Which prefix opens a transaction in a new session (window)?","o":["/o","/n","/x","/d"],"e":"/o opens the transaction in a new session, so you keep the current screen open."},"fr":{"q":"Quel préfixe ouvre une transaction dans une nouvelle session (fenêtre) ?","o":["/o","/n","/x","/d"],"e":"/o ouvre la transaction dans une nouvelle session : l'écran en cours reste ouvert."}},{"id":13,"l":2,"en":{"q":"Transaction codes ending in 01, 02 and 03 usually mean:","o":["Create, change, display","Plan, produce, ship","Low, medium, high priority","Monday, Tuesday, Wednesday"],"e":"For example MM01, MM02 and MM03 create, change and display a material."},"fr":{"q":"Les codes de transaction finissant par 01, 02 et 03 signifient en général :","o":["Créer, modifier, afficher","Planifier, produire, expédier","Priorité basse, moyenne, haute","Lundi, mardi, mercredi"],"e":"Par exemple, MM01, MM02 et MM03 créent, modifient et affichent un article."}},{"id":14,"l":2,"en":{"q":"Which of these is master data?","o":["A material","A goods movement","A confirmation","A production order"],"e":"Master data describes things that last: materials, BOMs, work centers, routings, suppliers."},"fr":{"q":"Lequel de ces éléments est une donnée de base ?","o":["Un article","Un mouvement de stock","Une confirmation","Un ordre de fabrication"],"e":"Les données de base décrivent ce qui dure : articles, nomenclatures, postes de travail, gammes, fournisseurs."}},{"id":15,"l":2,"en":{"q":"Which of these is transactional data?","o":["A goods receipt posting","A work center","A bill of materials","A material"],"e":"Transactional data records events: orders, confirmations, goods movements. Each one creates a document."},"fr":{"q":"Lequel de ces éléments est une donnée de mouvement ?","o":["Une entrée de marchandises comptabilisée","Un poste de travail","Une nomenclature","Un article"],"e":"Les données de mouvement enregistrent des événements : ordres, confirmations, mouvements de stock. Chacun crée un document."}},{"id":16,"l":2,"en":{"q":"In SAP GUI, which key shows the list of possible values for a field?","o":["F4","F1","F8","F12"],"e":"F4 opens the input help (search help). F1 explains the field, F8 executes, F12 cancels."},"fr":{"q":"Dans SAP GUI, quelle touche affiche la liste des valeurs possibles d'un champ ?","o":["F4","F1","F8","F12"],"e":"F4 ouvre l'aide à la saisie. F1 explique le champ, F8 exécute, F12 annule."}},{"id":17,"l":2,"en":{"q":"In SAP GUI, which key shows help on a field?","o":["F1","F3","F4","F5"],"e":"F1 explains what the field means. F3 goes back, F4 lists the possible values."},"fr":{"q":"Dans SAP GUI, quelle touche affiche l'aide sur un champ ?","o":["F1","F3","F4","F5"],"e":"F1 explique la signification du champ. F3 revient en arrière, F4 liste les valeurs possibles."}},{"id":18,"l":2,"en":{"q":"Why may a user not see an app or a transaction?","o":["Their role does not include it","The screen is too small","SAP is closed at night","The app only exists in German"],"e":"Access is given through roles and authorisations. To learn, ask for display-only roles."},"fr":{"q":"Pourquoi un utilisateur peut-il ne pas voir une application ou une transaction ?","o":["Son rôle ne la contient pas","Son écran est trop petit","SAP ferme la nuit","L'application n'existe qu'en allemand"],"e":"L'accès passe par des rôles et des autorisations. Pour apprendre, demandez des rôles en affichage seul."}},{"id":19,"l":2,"en":{"q":"What does a goods movement create in SAP?","o":["A material document","A new material","A new plant","A bill of materials"],"e":"Each goods movement is recorded in a material document with its own number, and usually an accounting document too."},"fr":{"q":"Que crée un mouvement de stock dans SAP ?","o":["Un document article","Un nouvel article","Une nouvelle division","Une nomenclature"],"e":"Chaque mouvement de stock est enregistré dans un document article avec son propre numéro, et en général aussi dans un document comptable."}},{"id":20,"l":3,"en":{"q":"What is the material master?","o":["The central record of a material","The list of components of a product","The sequence of operations","A stock count"],"e":"One material master record holds everything SAP knows about an item, organised in views and by plant."},"fr":{"q":"Qu'est-ce que la fiche article ?","o":["L'enregistrement central d'un article","La liste des composants d'un produit","La suite des opérations","Un inventaire"],"e":"La fiche article réunit tout ce que SAP sait d'un article, organisé en vues et par division."}},{"id":21,"l":3,"en":{"q":"Data in the material master is organised in:","o":["Views","Levels","Yearly folders","Language pages"],"e":"Basic data, purchasing, MRP, work scheduling, quality, accounting: each department fills its own views."},"fr":{"q":"Les données de la fiche article sont organisées en :","o":["Vues","Niveaux","Dossiers annuels","Pages par langue"],"e":"Données de base, achats, MRP, préparation du travail, qualité, comptabilité : chaque service remplit ses vues."}},{"id":22,"l":3,"en":{"q":"Which standard material type is used for a finished product?","o":["FERT","ROH","HALB","ERSA"],"e":"FERT is a finished product, ROH a raw material, HALB a semi-finished product, ERSA a spare part."},"fr":{"q":"Quel type d'article standard est utilisé pour un produit fini ?","o":["FERT","ROH","HALB","ERSA"],"e":"FERT : produit fini. ROH : matière première. HALB : produit semi-fini. ERSA : pièce de rechange."}},{"id":23,"l":3,"en":{"q":"Which standard material type is used for a raw material?","o":["ROH","FERT","HAWA","HALB"],"e":"ROH (from the German Rohstoff) is a raw material. HAWA is a trading good, bought and resold."},"fr":{"q":"Quel type d'article standard est utilisé pour une matière première ?","o":["ROH","FERT","HAWA","HALB"],"e":"ROH (de l'allemand Rohstoff) désigne une matière première. HAWA est une marchandise achetée et revendue."}},{"id":24,"l":3,"en":{"q":"What does a bill of materials list?","o":["The components needed to make a product","The machines of a plant","The operators of a shift","The customers of a product"],"e":"The BOM gives each component with its quantity for a base quantity of the product."},"fr":{"q":"Que contient une nomenclature ?","o":["Les composants nécessaires pour fabriquer un produit","Les machines d'une division","Les opérateurs d'une équipe","Les clients d'un produit"],"e":"La nomenclature donne chaque composant avec sa quantité, pour une quantité de base du produit."}},{"id":25,"l":3,"en":{"q":"What does a routing describe?","o":["The sequence of operations to make a product","The price of a product","The storage bins","The suppliers"],"e":"Each operation of the routing is done at a work center, with standard times."},"fr":{"q":"Que décrit une gamme ?","o":["La suite des opérations pour fabriquer un produit","Le prix d'un produit","Les emplacements de stockage","Les fournisseurs"],"e":"Chaque opération de la gamme se fait sur un poste de travail, avec des temps standard."}},{"id":26,"l":3,"en":{"q":"Where is an operation carried out?","o":["At a work center","At a company code","At a storage location","At a client"],"e":"A work center is a machine, a line or a team, with its capacity and its costs."},"fr":{"q":"Où une opération est-elle réalisée ?","o":["Sur un poste de travail","Dans une société","Dans un magasin","Dans un mandant"],"e":"Un poste de travail est une machine, une ligne ou une équipe, avec sa capacité et ses coûts."}},{"id":27,"l":3,"en":{"q":"What does the control key of an operation define?","o":["How the operation is processed, for example whether it must be confirmed","The operator's password","The colour of labels","The material type"],"e":"The control key says, for example, whether the operation is scheduled, costed, confirmed or done by a subcontractor."},"fr":{"q":"Que définit la clé de commande d'une opération ?","o":["La façon dont l'opération est traitée, par exemple si elle doit être confirmée","Le mot de passe de l'opérateur","La couleur des étiquettes","Le type d'article"],"e":"La clé de commande indique par exemple si l'opération est ordonnancée, valorisée, confirmée ou sous-traitée."}},{"id":28,"l":3,"en":{"q":"What does a production version link together for a material?","o":["A BOM alternative and a routing","A plant and a customer","Two storage locations","A supplier and a price"],"e":"The production version tells SAP which BOM and which routing to use, for a validity period and a lot-size range."},"fr":{"q":"Qu'est-ce qu'une version de fabrication relie pour un article ?","o":["Une variante de nomenclature et une gamme","Une division et un client","Deux magasins","Un fournisseur et un prix"],"e":"La version de fabrication indique à SAP quelle nomenclature et quelle gamme utiliser, pour une période et une plage de quantités."}},{"id":29,"l":3,"en":{"q":"In S/4HANA, for materials produced in-house, a production version is:","o":["Mandatory for planning","Forbidden","Only needed for exports","Only used for spare parts"],"e":"In S/4HANA the BOM is selected through the production version, so MRP needs one for every material made in-house."},"fr":{"q":"Dans S/4HANA, pour les articles fabriqués en interne, la version de fabrication est :","o":["Obligatoire pour la planification","Interdite","Nécessaire seulement à l'export","Réservée aux pièces de rechange"],"e":"Dans S/4HANA, la nomenclature est choisie via la version de fabrication : le MRP en a besoin pour chaque article fabriqué en interne."}},{"id":30,"l":4,"en":{"q":"What does MRP stand for?","o":["Material requirements planning","Machine repair procedure","Maximum run performance","Master routing plan"],"e":"MRP works out what must be made or bought, and when, to cover demand."},"fr":{"q":"Que signifie MRP ?","o":["Material requirements planning (calcul des besoins)","Machine repair procedure","Maximum run performance","Master routing plan"],"e":"Le MRP calcule ce qu'il faut fabriquer ou acheter, et quand, pour couvrir la demande."}},{"id":31,"l":4,"en":{"q":"What does MRP propose for in-house production?","o":["Planned orders","Sales orders","Invoices","Inspection lots"],"e":"Planned orders are proposals. They become production orders when they are converted."},"fr":{"q":"Que propose le MRP pour la fabrication interne ?","o":["Des ordres planifiés","Des commandes clients","Des factures","Des lots de contrôle"],"e":"Les ordres planifiés sont des propositions. Ils deviennent des ordres de fabrication lorsqu'on les convertit."}},{"id":32,"l":4,"en":{"q":"For materials bought from suppliers, MRP proposes:","o":["Purchase requisitions","Production orders","Work centers","Batches"],"e":"A purchase requisition is turned into a purchase order by the buyers."},"fr":{"q":"Pour les articles achetés chez des fournisseurs, le MRP propose :","o":["Des demandes d'achat","Des ordres de fabrication","Des postes de travail","Des lots"],"e":"Les acheteurs transforment ensuite la demande d'achat en commande d'achat."}},{"id":33,"l":4,"en":{"q":"Which transaction runs MRP Live in S/4HANA?","o":["MD01N","MD04","CO11N","MIGO"],"e":"MD01N is MRP Live, the planning run optimised for SAP HANA. MD04 shows its results for one material."},"fr":{"q":"Quelle transaction lance MRP Live dans S/4HANA ?","o":["MD01N","MD04","CO11N","MIGO"],"e":"MD01N est MRP Live, le calcul des besoins optimisé pour SAP HANA. MD04 en montre le résultat pour un article."}},{"id":34,"l":4,"en":{"q":"Which transaction shows the stock/requirements list of a material?","o":["MD04","MM01","CS01","IW21"],"e":"MD04 shows stock, requirements and receipts in date order: the live view of planning."},"fr":{"q":"Quelle transaction affiche la liste des besoins et des stocks d'un article ?","o":["MD04","MM01","CS01","IW21"],"e":"MD04 affiche le stock, les besoins et les entrées prévues par date : la vue en direct de la planification."}},{"id":35,"l":4,"en":{"q":"What does procurement type E mean?","o":["In-house production","External procurement","Both in-house and external","Engineering only"],"e":"E is in-house production, F external procurement, X both."},"fr":{"q":"Que signifie le type d'approvisionnement E ?","o":["Fabrication interne","Approvisionnement externe","Les deux","Bureau d'études uniquement"],"e":"E : fabrication interne. F : approvisionnement externe. X : les deux."}},{"id":36,"l":4,"en":{"q":"What does lot size EX mean?","o":["Lot-for-lot: exactly the quantity missing","A fixed quantity","Replenish up to a maximum stock","Excluded from planning"],"e":"EX orders exactly what is missing. FX uses a fixed quantity, HB fills up to a maximum stock level."},"fr":{"q":"Que signifie la taille de lot EX ?","o":["Lot pour lot : exactement la quantité manquante","Une quantité fixe","Réapprovisionner jusqu'à un stock maximum","Exclu de la planification"],"e":"EX commande exactement ce qui manque. FX utilise une quantité fixe, HB remplit jusqu'à un stock maximum."}},{"id":37,"l":4,"en":{"q":"Requirements for components, created by exploding the BOM, are called:","o":["Dependent requirements","Independent requirements","Sales requirements","Customer reservations"],"e":"They depend on the planned production of the parent product, unlike the independent demand of customers or forecasts."},"fr":{"q":"Les besoins en composants, créés en éclatant la nomenclature, s'appellent :","o":["Des besoins dépendants","Des besoins indépendants","Des besoins de vente","Des réservations clients"],"e":"Ils dépendent de la production prévue du produit parent, contrairement à la demande indépendante des clients ou des prévisions."}},{"id":38,"l":4,"en":{"q":"100 pumps are needed, 20 are in stock, nothing is on order, the lot size is lot-for-lot. What does MRP propose?","o":["A planned order for 80","A planned order for 100","A planned order for 120","Nothing"],"e":"Net requirement = demand − stock − open receipts = 100 − 20 − 0 = 80."},"fr":{"q":"Il faut 100 pompes, 20 sont en stock, rien n'est commandé, la taille de lot est lot pour lot. Que propose le MRP ?","o":["Un ordre planifié de 80","Un ordre planifié de 100","Un ordre planifié de 120","Rien"],"e":"Besoin net = demande − stock − entrées prévues = 100 − 20 − 0 = 80."}},{"id":39,"l":4,"en":{"q":"What happens to a planned order before production starts?","o":["It is converted into a production order","It is deleted and recreated","It is sent to the customer","It becomes a batch"],"e":"Conversion turns the proposal into a real order, with components and operations, ready to be released."},"fr":{"q":"Que devient un ordre planifié avant le début de la production ?","o":["Il est converti en ordre de fabrication","Il est supprimé puis recréé","Il est envoyé au client","Il devient un lot"],"e":"La conversion transforme la proposition en ordre réel, avec ses composants et ses opérations, prêt à être lancé."}},{"id":40,"l":5,"en":{"q":"Where do the operations of a production order come from?","o":["The routing","The BOM","The customer order","The work center"],"e":"When the order is created, SAP copies the operations of the routing chosen by the production version."},"fr":{"q":"D'où viennent les opérations d'un ordre de fabrication ?","o":["De la gamme","De la nomenclature","De la commande client","Du poste de travail"],"e":"À la création de l'ordre, SAP copie les opérations de la gamme choisie par la version de fabrication."}},{"id":41,"l":5,"en":{"q":"Where do the components of a production order come from?","o":["The BOM","The routing","The inspection plan","The maintenance plan"],"e":"The BOM is exploded for the order quantity, and each component is reserved."},"fr":{"q":"D'où viennent les composants d'un ordre de fabrication ?","o":["De la nomenclature","De la gamme","Du plan de contrôle","Du plan d'entretien"],"e":"La nomenclature est éclatée pour la quantité de l'ordre, et chaque composant est réservé."}},{"id":42,"l":5,"en":{"q":"What does the status REL mean on a production order?","o":["Released","Relocated","Reliable","Rejected"],"e":"Once released, the order can be printed, sent to the MES, and receive goods movements and confirmations."},"fr":{"q":"Que signifie le statut REL d'un ordre de fabrication ?","o":["Lancé (released)","Déplacé","Fiable","Refusé"],"e":"Une fois lancé, l'ordre peut être imprimé, envoyé au MES, et recevoir des mouvements de stock et des confirmations."}},{"id":43,"l":5,"en":{"q":"What does the status TECO mean?","o":["Technically completed","Test confirmation","Temporary cost","Technical error"],"e":"TECO closes the order for logistics: no more production is expected. Costs are settled afterwards."},"fr":{"q":"Que signifie le statut TECO ?","o":["Techniquement terminé","Confirmation de test","Coût temporaire","Erreur technique"],"e":"TECO clôt l'ordre côté logistique : plus aucune production n'est attendue. Les coûts sont imputés ensuite."}},{"id":44,"l":5,"en":{"q":"Which movement type issues components to a production order?","o":["261","101","311","551"],"e":"261 is the goods issue to an order. Its reversal is 262."},"fr":{"q":"Quel type de mouvement sort les composants vers un ordre de fabrication ?","o":["261","101","311","551"],"e":"261 est la sortie de marchandises vers un ordre. Son annulation est 262."}},{"id":45,"l":5,"en":{"q":"Which movement type posts the goods receipt of a production order?","o":["101","261","201","311"],"e":"101 is the goods receipt, used for production orders and purchase orders alike."},"fr":{"q":"Quel type de mouvement comptabilise l'entrée de marchandises d'un ordre de fabrication ?","o":["101","261","201","311"],"e":"101 est l'entrée de marchandises, utilisée aussi bien pour les ordres de fabrication que pour les commandes d'achat."}},{"id":46,"l":5,"en":{"q":"What is backflushing?","o":["Issuing components automatically when an operation is confirmed","Cleaning a machine","Cancelling an order","Returning goods to a supplier"],"e":"With backflushing, nobody posts the goods issue by hand: the confirmation does it."},"fr":{"q":"Qu'est-ce que le prélèvement rétroactif (backflush) ?","o":["La sortie automatique des composants lors de la confirmation d'une opération","Le nettoyage d'une machine","L'annulation d'un ordre","Le retour de marchandises à un fournisseur"],"e":"Avec le prélèvement rétroactif, personne ne saisit la sortie de stock à la main : la confirmation s'en charge."}},{"id":47,"l":5,"en":{"q":"Which SAP GUI transaction confirms an operation?","o":["CO11N","MD04","MM03","IW31"],"e":"CO11N is the single-screen confirmation. CO13 cancels a confirmation."},"fr":{"q":"Quelle transaction SAP GUI confirme une opération ?","o":["CO11N","MD04","MM03","IW31"],"e":"CO11N est la confirmation sur un seul écran. CO13 annule une confirmation."}},{"id":48,"l":5,"en":{"q":"In a confirmation, what does yield mean?","o":["The good quantity produced","The scrap","The planned quantity","The machine speed"],"e":"A confirmation reports yield (good parts), scrap, rework and the times spent."},"fr":{"q":"Dans une confirmation, que signifie le rendement (yield) ?","o":["La quantité bonne produite","Le rebut","La quantité prévue","La vitesse de la machine"],"e":"Une confirmation indique la quantité bonne, le rebut, les retouches et les temps passés."}},{"id":49,"l":5,"en":{"q":"What can only be done once a production order is released?","o":["Post confirmations and goods movements","Create its BOM","Create the material","Delete the plant"],"e":"Before release, the order is only planned: SAP does not accept confirmations or goods issues against it."},"fr":{"q":"Que ne peut-on faire qu'une fois l'ordre de fabrication lancé ?","o":["Saisir des confirmations et des mouvements de stock","Créer sa nomenclature","Créer l'article","Supprimer la division"],"e":"Avant le lancement, l'ordre est seulement planifié : SAP refuse les confirmations et les sorties de stock."}},{"id":50,"l":6,"en":{"q":"What identifies the kind of goods movement?","o":["The movement type","The plant","The user name","The printer"],"e":"The three-digit movement type tells SAP what happens: receipt, issue, transfer, scrapping, and how to post it."},"fr":{"q":"Qu'est-ce qui identifie la nature d'un mouvement de stock ?","o":["Le type de mouvement","La division","Le nom d'utilisateur","L'imprimante"],"e":"Le type de mouvement à trois chiffres indique à SAP ce qui se passe (entrée, sortie, transfert, mise au rebut) et comment le comptabiliser."}},{"id":51,"l":6,"en":{"q":"What is movement type 311 used for?","o":["Transfer between storage locations","Goods receipt from production","Scrapping","Issue to a cost center"],"e":"311 moves stock from one storage location to another in one step."},"fr":{"q":"À quoi sert le type de mouvement 311 ?","o":["Au transfert entre magasins","À l'entrée de production","À la mise au rebut","À la sortie vers un centre de coûts"],"e":"311 déplace du stock d'un magasin à un autre en une seule étape."}},{"id":52,"l":6,"en":{"q":"What is movement type 551 used for?","o":["Withdrawal for scrapping","Goods receipt","Transfer posting","Physical inventory count"],"e":"551 takes damaged or unusable stock out of inventory as scrap."},"fr":{"q":"À quoi sert le type de mouvement 551 ?","o":["À la sortie pour mise au rebut","À l'entrée de marchandises","Au transfert","Au comptage d'inventaire"],"e":"551 sort du stock les articles abîmés ou inutilisables, mis au rebut."}},{"id":53,"l":6,"en":{"q":"What is movement type 201 used for?","o":["Goods issue to a cost center","Goods issue to a production order","Goods receipt","Return to a supplier"],"e":"201 is used for consumption that is not linked to an order, for example cleaning products charged to a department."},"fr":{"q":"À quoi sert le type de mouvement 201 ?","o":["À la sortie vers un centre de coûts","À la sortie vers un ordre de fabrication","À l'entrée de marchandises","Au retour fournisseur"],"e":"201 sert aux consommations non liées à un ordre, par exemple des produits d'entretien imputés à un service."}},{"id":54,"l":6,"en":{"q":"How is a goods movement usually reversed?","o":["With the next movement type, for example 102 for 101","By deleting the document","By setting the quantity to zero","It cannot be reversed"],"e":"Documents are never deleted: a reversal posts the opposite movement, so the history stays complete."},"fr":{"q":"Comment annule-t-on en général un mouvement de stock ?","o":["Avec le type de mouvement suivant, par exemple 102 pour 101","En supprimant le document","En mettant la quantité à zéro","C'est impossible"],"e":"On ne supprime jamais un document : l'annulation comptabilise le mouvement inverse, et l'historique reste complet."}},{"id":55,"l":6,"en":{"q":"Which three stock types can a material have in a storage location?","o":["Unrestricted-use, quality inspection, blocked","Hot, warm, cold","Raw, semi-finished, finished","Open, closed, archived"],"e":"Only unrestricted-use stock can be consumed freely. Quality inspection stock waits for a decision, blocked stock cannot be used."},"fr":{"q":"Quels sont les trois types de stock d'un article dans un magasin ?","o":["Libre utilisation, contrôle qualité, bloqué","Chaud, tiède, froid","Brut, semi-fini, fini","Ouvert, fermé, archivé"],"e":"Seul le stock en libre utilisation peut être consommé librement. Le stock en contrôle attend une décision, le stock bloqué est inutilisable."}},{"id":56,"l":6,"en":{"q":"Which SAP GUI transaction handles most goods movements?","o":["MIGO","MD04","CS03","CR03"],"e":"MIGO groups goods receipts, issues, transfers and their display in one transaction."},"fr":{"q":"Quelle transaction SAP GUI gère la plupart des mouvements de stock ?","o":["MIGO","MD04","CS03","CR03"],"e":"MIGO réunit les entrées, sorties, transferts et leur affichage dans une seule transaction."}},{"id":57,"l":6,"en":{"q":"Which transaction gives a stock overview of a material across plants and storage locations?","o":["MMBE","MIGO","CO01","QA32"],"e":"MMBE shows the stock of a material at every level, by stock type."},"fr":{"q":"Quelle transaction donne une vue du stock d'un article par division et par magasin ?","o":["MMBE","MIGO","CO01","QA32"],"e":"MMBE affiche le stock d'un article à tous les niveaux, par type de stock."}},{"id":58,"l":6,"en":{"q":"Besides the material document, what does a valued goods movement usually create?","o":["An accounting document","A new material","A routing","A maintenance order"],"e":"Stock has a value, so moving it changes the accounts: logistics and finance stay in step."},"fr":{"q":"En plus du document article, que crée en général un mouvement de stock valorisé ?","o":["Un document comptable","Un nouvel article","Une gamme","Un ordre d'entretien"],"e":"Le stock a une valeur : le déplacer modifie la comptabilité, et la logistique et la finance restent alignées."}},{"id":59,"l":6,"en":{"q":"Movement type 321 moves stock:","o":["From quality inspection to unrestricted-use","From blocked to scrap","From one plant to another","From the supplier to the plant"],"e":"321 releases stock from quality inspection. A usage decision in QM often posts it automatically."},"fr":{"q":"Le type de mouvement 321 déplace le stock :","o":["Du contrôle qualité vers la libre utilisation","Du bloqué vers le rebut","D'une division à une autre","Du fournisseur vers la division"],"e":"321 libère le stock du contrôle qualité. Une décision d'emploi en QM le comptabilise souvent automatiquement."}},{"id":60,"l":7,"en":{"q":"What is an inspection lot?","o":["A request to inspect a quantity of material","A batch of raw material","A warehouse aisle","A machine fault"],"e":"The inspection lot gathers what must be checked, the results and the final decision."},"fr":{"q":"Qu'est-ce qu'un lot de contrôle ?","o":["Une demande de contrôle d'une quantité d'article","Un lot de matière première","Une allée d'entrepôt","Une panne machine"],"e":"Le lot de contrôle regroupe ce qu'il faut vérifier, les résultats et la décision finale."}},{"id":61,"l":7,"en":{"q":"Inspection lot origin 01 is created for:","o":["A goods receipt for a purchase order","An in-process inspection","A goods receipt from production","Customer returns"],"e":"Origin 01 is the incoming inspection of supplier deliveries."},"fr":{"q":"L'origine de lot de contrôle 01 est créée pour :","o":["Une entrée de marchandises sur commande d'achat","Un contrôle en cours de fabrication","Une entrée de production","Des retours clients"],"e":"L'origine 01 correspond au contrôle à réception des livraisons fournisseurs."}},{"id":62,"l":7,"en":{"q":"Inspection lot origin 03 is used for:","o":["In-process inspection during production","A goods receipt for a purchase order","A stock transfer","A supplier audit"],"e":"An origin 03 lot is usually created when the production order is released, and inspected along the operations."},"fr":{"q":"L'origine de lot de contrôle 03 sert :","o":["Au contrôle en cours de fabrication","À l'entrée sur commande d'achat","Au transfert de stock","À l'audit fournisseur"],"e":"Un lot d'origine 03 est en général créé au lancement de l'ordre de fabrication et contrôlé au fil des opérations."}},{"id":63,"l":7,"en":{"q":"Inspection lot origin 04 is used for:","o":["A goods receipt from production","A goods issue","A customer complaint","A purchase order"],"e":"Origin 04 inspects what production delivers to stock."},"fr":{"q":"L'origine de lot de contrôle 04 sert :","o":["À l'entrée de marchandises depuis la production","À la sortie de stock","À la réclamation client","À la commande d'achat"],"e":"L'origine 04 contrôle ce que la production livre en stock."}},{"id":64,"l":7,"en":{"q":"With origin 04, where do produced goods usually go at goods receipt?","o":["Into quality inspection stock","Straight to the customer","Always into blocked stock","Into scrap"],"e":"Origin 04 lots are stock-relevant: the goods wait in quality inspection stock until the usage decision."},"fr":{"q":"Avec l'origine 04, où vont en général les produits à l'entrée de marchandises ?","o":["En stock de contrôle qualité","Directement chez le client","Toujours en stock bloqué","Au rebut"],"e":"Les lots d'origine 04 concernent le stock : les produits attendent en stock de contrôle jusqu'à la décision d'emploi."}},{"id":65,"l":7,"en":{"q":"What closes an inspection lot and decides what happens to the stock?","o":["The usage decision","The goods issue","The MRP run","The settlement"],"e":"The usage decision accepts or rejects the lot and can post the stock to unrestricted-use, blocked or scrap."},"fr":{"q":"Qu'est-ce qui clôt un lot de contrôle et décide du sort du stock ?","o":["La décision d'emploi","La sortie de stock","Le calcul MRP","L'imputation"],"e":"La décision d'emploi accepte ou refuse le lot et peut transférer le stock en libre utilisation, en bloqué ou au rebut."}},{"id":66,"l":7,"en":{"q":"Which SAP GUI transaction records inspection results?","o":["QE51N","MD04","MIGO","IW21"],"e":"QE51N is the worklist for results recording. QA32 is the worklist for inspection lots and usage decisions."},"fr":{"q":"Quelle transaction SAP GUI enregistre les résultats de contrôle ?","o":["QE51N","MD04","MIGO","IW21"],"e":"QE51N est la liste de travail pour la saisie des résultats. QA32 est celle des lots de contrôle et des décisions d'emploi."}},{"id":67,"l":7,"en":{"q":"A characteristic to inspect, reused in many inspection plans, is called:","o":["A master inspection characteristic","A work center","A material type","A movement type"],"e":"Master inspection characteristics (for example a diameter or a pressure) keep definitions consistent across plans."},"fr":{"q":"Une caractéristique de contrôle réutilisée dans de nombreux plans s'appelle :","o":["Une caractéristique de contrôle de référence","Un poste de travail","Un type d'article","Un type de mouvement"],"e":"Les caractéristiques de référence (un diamètre, une pression…) gardent des définitions cohérentes d'un plan à l'autre."}},{"id":68,"l":7,"en":{"q":"In the SAP standard, notification type Q2 is:","o":["A complaint against a supplier","A customer complaint","An internal problem","A maintenance request"],"e":"Q1 is a customer complaint, Q2 a complaint against a supplier, Q3 an internal problem."},"fr":{"q":"Dans le standard SAP, l'avis de type Q2 est :","o":["Une réclamation contre un fournisseur","Une réclamation client","Un problème interne","Une demande d'entretien"],"e":"Q1 : réclamation client. Q2 : réclamation contre un fournisseur. Q3 : problème interne."}},{"id":69,"l":7,"en":{"q":"How can measurements from a test bench reach SAP QM?","o":["Through the MES or an interface that records results against the inspection lot","The PLC writes straight into the SAP database","Only by email to the SAP administrator","They cannot"],"e":"Results are posted through official interfaces, never by writing into SAP's tables."},"fr":{"q":"Comment des mesures d'un banc de test peuvent-elles arriver dans SAP QM ?","o":["Par le MES ou une interface qui enregistre les résultats dans le lot de contrôle","L'automate écrit directement dans la base SAP","Uniquement par mail à l'administrateur SAP","C'est impossible"],"e":"Les résultats passent par des interfaces officielles, jamais par une écriture directe dans les tables SAP."}},{"id":70,"l":8,"en":{"q":"What does a functional location represent?","o":["A place in the plant's technical structure where objects are installed","A storage bin","A user's desk","A sales area"],"e":"Functional locations form a tree, for example plant, line, station, where equipment is installed."},"fr":{"q":"Que représente un poste technique ?","o":["Un emplacement de la structure technique de l'usine où des objets sont installés","Un emplacement de stockage","Le bureau d'un utilisateur","Une zone de vente"],"e":"Les postes techniques forment une arborescence (usine, ligne, station) où l'on installe les équipements."}},{"id":71,"l":8,"en":{"q":"What is an equipment in SAP?","o":["An individual physical object that can be installed and moved","A type of material document","A production version","A maintenance strategy"],"e":"An equipment (a pump, a motor) has its own history and can move from one functional location to another."},"fr":{"q":"Qu'est-ce qu'un équipement dans SAP ?","o":["Un objet physique individuel qu'on peut installer et déplacer","Un type de document article","Une version de fabrication","Une stratégie d'entretien"],"e":"Un équipement (une pompe, un moteur) a son propre historique et peut passer d'un poste technique à un autre."}},{"id":72,"l":8,"en":{"q":"In the SAP standard, notification type M2 is:","o":["A malfunction report","A maintenance request","An activity report","A customer complaint"],"e":"M1 is a maintenance request, M2 a malfunction report, M3 an activity report."},"fr":{"q":"Dans le standard SAP, l'avis de type M2 est :","o":["Un avis de panne","Une demande d'entretien","Un compte rendu d'activité","Une réclamation client"],"e":"M1 : demande d'entretien. M2 : avis de panne. M3 : compte rendu d'activité."}},{"id":73,"l":8,"en":{"q":"Which SAP GUI transaction creates a maintenance notification?","o":["IW21","IW31","CO01","MIGO"],"e":"IW21 creates a notification. IW31 creates a maintenance order."},"fr":{"q":"Quelle transaction SAP GUI crée un avis de maintenance ?","o":["IW21","IW31","CO01","MIGO"],"e":"IW21 crée un avis. IW31 crée un ordre d'entretien."}},{"id":74,"l":8,"en":{"q":"Which SAP GUI transaction creates a maintenance order?","o":["IW31","IW21","IE01","MD04"],"e":"IW31 creates the order. IE01 creates an equipment."},"fr":{"q":"Quelle transaction SAP GUI crée un ordre d'entretien ?","o":["IW31","IW21","IE01","MD04"],"e":"IW31 crée l'ordre. IE01 crée un équipement."}},{"id":75,"l":8,"en":{"q":"Where are the planned work, spare parts and costs of a repair recorded?","o":["In the maintenance order","In the functional location","In the material type","In the BOM header"],"e":"The maintenance order plans operations and parts, collects confirmations and costs."},"fr":{"q":"Où enregistre-t-on le travail prévu, les pièces et les coûts d'une réparation ?","o":["Dans l'ordre d'entretien","Dans le poste technique","Dans le type d'article","Dans l'en-tête de nomenclature"],"e":"L'ordre d'entretien planifie les opérations et les pièces, et rassemble les confirmations et les coûts."}},{"id":76,"l":8,"en":{"q":"Preventive maintenance based on a machine's cycles or operating hours is called:","o":["Performance-based (counter-based) maintenance","Time-based maintenance","Breakdown maintenance","Corrective maintenance"],"e":"Instead of every three months, the work is triggered every 10,000 cycles or 500 hours, for example."},"fr":{"q":"La maintenance préventive basée sur les cycles ou les heures de marche s'appelle :","o":["La maintenance selon compteur","La maintenance périodique","La maintenance après panne","La maintenance corrective"],"e":"Au lieu de tous les trois mois, l'intervention est déclenchée par exemple tous les 10 000 cycles ou toutes les 500 heures."}},{"id":77,"l":8,"en":{"q":"Which object holds a counter, such as operating hours, for an equipment?","o":["A measuring point","A storage location","A production version","A company code"],"e":"A measuring point defined as a counter keeps the readings that drive counter-based plans."},"fr":{"q":"Quel objet porte un compteur, par exemple d'heures de marche, pour un équipement ?","o":["Un point de mesure","Un magasin","Une version de fabrication","Une société"],"e":"Un point de mesure défini comme compteur garde les relevés qui pilotent les plans selon compteur."}},{"id":78,"l":8,"en":{"q":"A reading taken on a measuring point is recorded as:","o":["A measurement document","A material document","An inspection lot","A purchase order"],"e":"Each reading creates a measurement document with its value, date and time."},"fr":{"q":"Un relevé sur un point de mesure est enregistré comme :","o":["Un document de mesure","Un document article","Un lot de contrôle","Une commande d'achat"],"e":"Chaque relevé crée un document de mesure avec sa valeur, sa date et son heure."}},{"id":79,"l":8,"en":{"q":"Which shop-floor source naturally feeds counter readings?","o":["Cycle or hour counters in the PLC or the supervision","The ERP's own clock","The canteen system","Printed labels"],"e":"Machines already count cycles and hours: sending these values to SAP avoids manual readings."},"fr":{"q":"Quelle source de l'atelier alimente naturellement les relevés de compteur ?","o":["Les compteurs de cycles ou d'heures de l'automate ou de la supervision","L'horloge de l'ERP","Le système de la cantine","Les étiquettes imprimées"],"e":"Les machines comptent déjà leurs cycles et leurs heures : envoyer ces valeurs à SAP évite les relevés manuels."}},{"id":80,"l":9,"en":{"q":"What is a batch in SAP logistics?","o":["A quantity of material with the same characteristics, tracked together","A group of users","A set of transaction codes","A program run at night"],"e":"A batch groups units made or received under the same conditions, with one batch number."},"fr":{"q":"Qu'est-ce qu'un lot dans la logistique SAP ?","o":["Une quantité d'article aux mêmes caractéristiques, suivie ensemble","Un groupe d'utilisateurs","Un ensemble de codes de transaction","Un programme lancé la nuit"],"e":"Un lot regroupe des unités fabriquées ou reçues dans les mêmes conditions, sous un même numéro."}},{"id":81,"l":9,"en":{"q":"Batch management is activated:","o":["Per material","For the whole system only","Per user","Per printer"],"e":"Only materials that need traceability are batch-managed; others are not."},"fr":{"q":"La gestion par lots s'active :","o":["Par article","Pour tout le système seulement","Par utilisateur","Par imprimante"],"e":"Seuls les articles qui ont besoin de traçabilité sont gérés par lots."}},{"id":82,"l":9,"en":{"q":"What does batch classification use?","o":["Characteristics, such as expiry date or viscosity","Movement types","Work centers","Notification types"],"e":"Characteristic values describe each batch and can be used to search or select batches."},"fr":{"q":"Qu'utilise la classification des lots ?","o":["Des caractéristiques, comme la date de péremption ou la viscosité","Des types de mouvement","Des postes de travail","Des types d'avis"],"e":"Les valeurs de caractéristiques décrivent chaque lot et servent à chercher ou à choisir des lots."}},{"id":83,"l":9,"en":{"q":"What does SLED stand for?","o":["Shelf life expiration date","Standard lot entry document","Stock level evaluation date","Serial label encoding device"],"e":"SAP can calculate the SLED from the production date and the shelf life of the material."},"fr":{"q":"Que signifie SLED ?","o":["Shelf life expiration date (date limite de conservation)","Standard lot entry document","Stock level evaluation date","Serial label encoding device"],"e":"SAP peut calculer la date limite à partir de la date de fabrication et de la durée de conservation de l'article."}},{"id":84,"l":9,"en":{"q":"In batch determination, what does FEFO mean?","o":["First expired, first out","First entered, first out","Fixed entry, fixed output","Final expiry for orders"],"e":"FEFO picks the batch that expires first. FIFO picks the oldest batch."},"fr":{"q":"Dans la détermination des lots, que signifie FEFO ?","o":["Premier périmé, premier sorti","Premier entré, premier sorti","Entrée fixe, sortie fixe","Péremption finale des ordres"],"e":"FEFO choisit le lot qui périme le premier. FIFO choisit le lot le plus ancien."}},{"id":85,"l":9,"en":{"q":"Which question does backward traceability answer?","o":["Which component batches went into this product batch?","Which customers received this batch?","Where should this batch be stored?","Who created the material?"],"e":"Backward: from the product to its components and suppliers. Forward: from a batch to the products and customers."},"fr":{"q":"À quelle question répond la traçabilité ascendante ?","o":["Quels lots de composants sont entrés dans ce lot de produit ?","Quels clients ont reçu ce lot ?","Où ranger ce lot ?","Qui a créé l'article ?"],"e":"Ascendante : du produit vers ses composants et ses fournisseurs. Descendante : d'un lot vers les produits et les clients."}},{"id":86,"l":9,"en":{"q":"Which question does forward traceability answer?","o":["Where did this batch go: which products and customers?","Which supplier delivered it?","Which routing was used?","Which plant owns it?"],"e":"Forward traceability is what a recall needs: find every product and customer affected by one faulty batch."},"fr":{"q":"À quelle question répond la traçabilité descendante ?","o":["Où est allé ce lot : dans quels produits et chez quels clients ?","Quel fournisseur l'a livré ?","Quelle gamme a été utilisée ?","À quelle division appartient-il ?"],"e":"C'est la traçabilité dont un rappel a besoin : retrouver tous les produits et clients touchés par un lot défectueux."}},{"id":87,"l":9,"en":{"q":"Which tool gives an overview of batches and where they were used?","o":["The Batch Information Cockpit (BMBC)","MD04","CO11N","IW31"],"e":"BMBC lets you select batches by characteristics and follow their where-used relationships."},"fr":{"q":"Quel outil donne une vue des lots et de leurs utilisations ?","o":["Le cockpit d'information sur les lots (BMBC)","MD04","CO11N","IW31"],"e":"BMBC permet de sélectionner des lots par caractéristiques et de suivre leurs utilisations."}},{"id":88,"l":9,"en":{"q":"To track each individual unit, for example each pump, SAP uses:","o":["Serial numbers","Batches only","Movement types","Storage locations"],"e":"A batch tracks a group of units; a serial number tracks one unit."},"fr":{"q":"Pour suivre chaque unité individuellement, par exemple chaque pompe, SAP utilise :","o":["Des numéros de série","Seulement des lots","Des types de mouvement","Des magasins"],"e":"Un lot suit un groupe d'unités ; un numéro de série suit une seule unité."}},{"id":89,"l":9,"en":{"q":"Traceability in SAP is only as good as:","o":["The goods issues posted with the right batches","The number of users","The screen resolution","The colour of the labels"],"e":"If the line consumes batch B but SAP records batch A, the traceability is wrong. Scanning at the line helps."},"fr":{"q":"La traçabilité dans SAP ne vaut que ce que valent :","o":["Les sorties de stock saisies avec les bons lots","Le nombre d'utilisateurs","La résolution de l'écran","La couleur des étiquettes"],"e":"Si la ligne consomme le lot B mais que SAP enregistre le lot A, la traçabilité est fausse. Le scan en ligne aide beaucoup."}},{"id":90,"l":10,"en":{"q":"Why do PLCs rarely talk directly to SAP?","o":["Machine signals must be translated into business events by an MES or a gateway","SAP does not support Ethernet","PLCs have no clock","SAP only reads paper"],"e":"A PLC knows tags and counters; SAP knows orders and confirmations. Something has to translate between the two."},"fr":{"q":"Pourquoi les automates parlent-ils rarement directement à SAP ?","o":["Les signaux machine doivent être traduits en événements de gestion par un MES ou une passerelle","SAP ne gère pas Ethernet","Les automates n'ont pas d'horloge","SAP ne lit que le papier"],"e":"Un automate connaît des variables et des compteurs ; SAP connaît des ordres et des confirmations. Il faut traduire entre les deux."}},{"id":91,"l":10,"en":{"q":"What is an IDoc?","o":["SAP's format for asynchronous messages","A PLC data block","An OPC UA node","A SCADA alarm"],"e":"IDocs are sent, queued and processed later, which makes them robust when the other side is busy or offline."},"fr":{"q":"Qu'est-ce qu'un IDoc ?","o":["Le format de SAP pour les messages asynchrones","Un bloc de données d'automate","Un nœud OPC UA","Une alarme SCADA"],"e":"Les IDocs sont envoyés, mis en file et traités plus tard : ils résistent bien quand l'autre côté est occupé ou hors ligne."}},{"id":92,"l":10,"en":{"q":"Which IDoc message type is commonly used to send production orders to an MES?","o":["LOIPRO","ORDERS","INVOIC","DEBMAS"],"e":"LOIPRO carries production orders. ORDERS is for purchase and sales orders, INVOIC for invoices, DEBMAS for customers."},"fr":{"q":"Quel type de message IDoc sert couramment à envoyer les ordres de fabrication à un MES ?","o":["LOIPRO","ORDERS","INVOIC","DEBMAS"],"e":"LOIPRO transporte les ordres de fabrication. ORDERS sert aux commandes, INVOIC aux factures, DEBMAS aux clients."}},{"id":93,"l":10,"en":{"q":"What is a BAPI?","o":["A function in SAP that external programs can call","A type of PLC","A database table","A network cable"],"e":"BAPIs are called through RFC and answer straight away, for example to post a confirmation."},"fr":{"q":"Qu'est-ce qu'une BAPI ?","o":["Une fonction de SAP que des programmes externes peuvent appeler","Un type d'automate","Une table de base de données","Un câble réseau"],"e":"Les BAPI s'appellent par RFC et répondent immédiatement, par exemple pour saisir une confirmation."}},{"id":94,"l":10,"en":{"q":"Where are the OData APIs of S/4HANA documented?","o":["On the SAP Business Accelerator Hub","On the PLC's web server","Only in the SAP GUI help","On the MES vendor's website"],"e":"api.sap.com lists the APIs, such as the Production Order API and the Production Order Confirmation API, with their fields."},"fr":{"q":"Où sont documentées les API OData de S/4HANA ?","o":["Sur le SAP Business Accelerator Hub","Sur le serveur web de l'automate","Uniquement dans l'aide de SAP GUI","Sur le site de l'éditeur du MES"],"e":"api.sap.com liste les API, comme celles des ordres de fabrication et de leurs confirmations, avec leurs champs."}},{"id":95,"l":10,"en":{"q":"Which SAP component reads OPC UA servers in the plant network?","o":["SAP Plant Connectivity (PCo)","SAP GUI","MRP Live","The material master"],"e":"PCo runs as a Windows service in the plant network. With SAP Digital Manufacturing, the Production Connector plays this role."},"fr":{"q":"Quel composant SAP lit les serveurs OPC UA du réseau de l'usine ?","o":["SAP Plant Connectivity (PCo)","SAP GUI","MRP Live","La fiche article"],"e":"PCo tourne comme service Windows dans le réseau de l'usine. Avec SAP Digital Manufacturing, c'est le Production Connector qui joue ce rôle."}},{"id":96,"l":10,"en":{"q":"Which transaction lets you reprocess IDocs in error?","o":["BD87","MD04","CO11N","MM03"],"e":"BD87 shows IDocs by status and lets you process them again once the cause is fixed."},"fr":{"q":"Quelle transaction permet de retraiter les IDocs en erreur ?","o":["BD87","MD04","CO11N","MM03"],"e":"BD87 affiche les IDocs par statut et permet de les retraiter une fois la cause corrigée."}},{"id":97,"l":10,"en":{"q":"In IEC 62443, how is the link between the office network and the plant network modelled?","o":["As a conduit between zones","As a batch","As a routing","As a material type"],"e":"Zones group assets with the same security needs; conduits are the controlled paths between them."},"fr":{"q":"Dans l'IEC 62443, comment modélise-t-on le lien entre le réseau bureautique et le réseau de l'usine ?","o":["Comme un conduit entre des zones","Comme un lot","Comme une gamme","Comme un type d'article"],"e":"Les zones regroupent des équipements aux mêmes besoins de sécurité ; les conduits sont les chemins contrôlés entre elles."}},{"id":98,"l":10,"en":{"q":"Which SAP user type suits an interface, because it cannot log on interactively?","o":["A system or communication user","A dialog user","A reference user","Any administrator"],"e":"Dialog users are for people. Interfaces get their own system or communication user, with only the rights they need."},"fr":{"q":"Quel type d'utilisateur SAP convient à une interface, parce qu'il ne peut pas ouvrir de session interactive ?","o":["Un utilisateur système ou de communication","Un utilisateur de dialogue","Un utilisateur de référence","N'importe quel administrateur"],"e":"Les utilisateurs de dialogue sont pour les personnes. Chaque interface a son utilisateur système ou de communication, avec les seuls droits nécessaires."}},{"id":99,"l":10,"en":{"q":"How should RFC traffic between SAP and a plant system be protected?","o":["Encrypted with SNC and filtered through the DMZ","Left open, since it is internal","Sent by email","Switched off every night"],"e":"SNC encrypts RFC traffic; the DMZ and firewall rules limit who can talk to whom."},"fr":{"q":"Comment protéger le trafic RFC entre SAP et un système de l'usine ?","o":["Chiffré avec SNC et filtré par la DMZ","Laissé ouvert, puisqu'il est interne","Envoyé par mail","Coupé chaque nuit"],"e":"SNC chiffre le trafic RFC ; la DMZ et les règles de pare-feu limitent qui peut parler à qui."}},{"id":100,"l":11,"en":{"q":"A company runs a non-SAP ERP. Which approach does it use to move to S/4HANA?","o":["A new implementation (greenfield)","A system conversion (brownfield)","A simple database upgrade","A PLC firmware update"],"e":"A system conversion only exists for SAP ECC systems. From any other ERP, S/4HANA is a new implementation, with selected data migrated."},"fr":{"q":"Une entreprise utilise un ERP qui n'est pas SAP. Quelle approche suit-elle pour passer à S/4HANA ?","o":["Une nouvelle implémentation (greenfield)","Une conversion de système (brownfield)","Une simple mise à jour de base de données","Une mise à jour du firmware des automates"],"e":"La conversion de système n'existe que pour les systèmes SAP ECC. Depuis tout autre ERP, S/4HANA est une nouvelle implémentation, avec une sélection de données migrées."}},{"id":101,"l":11,"en":{"q":"What does a system conversion (brownfield) do?","o":["It converts an existing SAP ECC system to S/4HANA, keeping its data and settings","It starts from an empty system","It copies only the master data","It replaces the MES"],"e":"The conversion keeps history and configuration; the price is that old habits and old customising come along too."},"fr":{"q":"Que fait une conversion de système (brownfield) ?","o":["Elle convertit un système SAP ECC existant en S/4HANA, en gardant ses données et ses réglages","Elle part d'un système vide","Elle ne copie que les données de base","Elle remplace le MES"],"e":"La conversion garde l'historique et le paramétrage ; en contrepartie, les vieilles habitudes et les anciens développements suivent aussi."}},{"id":102,"l":11,"en":{"q":"In SAP Activate, in which phase are the fit-to-standard workshops held?","o":["Explore","Discover","Deploy","Run"],"e":"In Explore, key users see the standard processes in a sandbox system and list the real gaps."},"fr":{"q":"Dans SAP Activate, dans quelle phase se tiennent les ateliers fit-to-standard ?","o":["Explore","Discover","Deploy","Run"],"e":"Pendant Explore, les utilisateurs clés découvrent les processus standard dans un système bac à sable et listent les vrais écarts."}},{"id":103,"l":11,"en":{"q":"When does SAP's mainstream maintenance for SAP ECC end?","o":["At the end of 2027","At the end of 2025","At the end of 2040","Never"],"e":"Mainstream maintenance ends at the end of 2027; optional extended maintenance, at a higher price, runs until the end of 2030."},"fr":{"q":"Quand se termine la maintenance standard de SAP ECC ?","o":["Fin 2027","Fin 2025","Fin 2040","Jamais"],"e":"La maintenance standard se termine fin 2027 ; une maintenance étendue optionnelle, plus chère, court jusqu'à fin 2030."}},{"id":104,"l":11,"en":{"q":"Why check field lengths in the MES, the HMIs and the labels before going live?","o":["SAP identifiers can be longer than the old ones, for example 12-character order numbers","SAP only uses letters","PLCs refuse numbers","There is no need"],"e":"Production order numbers have 12 characters in SAP, and material numbers can have up to 40 in S/4HANA. A barcode or a database field sized for the old ERP may cut them."},"fr":{"q":"Pourquoi vérifier la longueur des champs du MES, des IHM et des étiquettes avant le démarrage ?","o":["Les identifiants SAP peuvent être plus longs que les anciens, par exemple des numéros d'ordre de 12 caractères","SAP n'utilise que des lettres","Les automates refusent les chiffres","Ce n'est pas nécessaire"],"e":"Les numéros d'ordre de fabrication ont 12 caractères dans SAP, et les numéros d'article jusqu'à 40 dans S/4HANA. Un code-barres ou un champ de base de données taillé pour l'ancien ERP peut les tronquer."}},{"id":105,"l":11,"en":{"q":"What is hypercare?","o":["The period of reinforced support right after go-live","A backup of the old ERP","The cleansing of master data","A type of maintenance order"],"e":"During hypercare, the project team stays on hand to fix problems quickly, often for several weeks after go-live."},"fr":{"q":"Qu'est-ce que l'hypercare ?","o":["La période de support renforcé juste après le démarrage","Une sauvegarde de l'ancien ERP","Le nettoyage des données de base","Un type d'ordre d'entretien"],"e":"Pendant l'hypercare, l'équipe projet reste disponible pour corriger vite les problèmes, souvent plusieurs semaines après le démarrage."}}];
